<?php require_once __DIR__ . '/../includes/auth.php'; requireLogin(); require_once __DIR__ . '/../config/database.php'; // Only allow POST requests if ($_SERVER['REQUEST_METHOD'] !== 'POST') { header("Location: ../admin/borrowers.php"); exit; } // Get form values $borrowerCode = trim( $_POST['borrower_code'] ?? '' ); $fullName = trim( $_POST['full_name'] ?? '' ); $departmentId = $_POST['department_id'] ?? ''; $position = trim( $_POST['position'] ?? '' ); $contactNumber = trim( $_POST['contact_number'] ?? '' ); $email = trim( $_POST['email'] ?? '' ); // Validate required fields if ( $borrowerCode === '' || $fullName === '' || $departmentId === '' ) { header( "Location: ../admin/borrowers.php?error=required" ); exit; } try { // Check if borrower code already exists $check = $pdo->prepare(" SELECT id FROM borrowers WHERE borrower_code = ? LIMIT 1 "); $check->execute([ $borrowerCode ]); if ($check->fetch()) { header( "Location: ../admin/borrowers.php?error=duplicate" ); exit; } // Check that selected department exists $departmentCheck = $pdo->prepare(" SELECT id FROM departments WHERE id = ? AND status = 'Active' LIMIT 1 "); $departmentCheck->execute([ $departmentId ]); if (!$departmentCheck->fetch()) { header( "Location: ../admin/borrowers.php?error=department" ); exit; } // Insert borrower $stmt = $pdo->prepare(" INSERT INTO borrowers ( borrower_code, full_name, department_id, position, contact_number, email, status ) VALUES ( ?, ?, ?, ?, ?, ?, 'Active' ) "); $stmt->execute([ $borrowerCode, $fullName, $departmentId, $position ?: null, $contactNumber ?: null, $email ?: null ]); // Return to borrowers page header( "Location: ../admin/borrowers.php?success=added" ); exit; } catch (PDOException $e) { // Duplicate database value if ($e->getCode() === '23000') { header( "Location: ../admin/borrowers.php?error=duplicate" ); exit; } // Other database error die( "Unable to save borrower: " . htmlspecialchars($e->getMessage()) ); } ?>
